import {mkdir,readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {ProgramBuilder,instruction,imagePut,interactionPrompt,videoPlay,variable,expr as E} from 'galbox-sdk/port-kit';
import {parseProgram,string,bool} from 'galbox-sdk/protocol';
import {inspectResource,createReleaseManifest} from 'galbox-sdk/release';
const root='tests/player-app/public/interactive';await mkdir(root+'/assets',{recursive:true});const standard=parseProgram(JSON.parse(await readFile('tests/fixtures/game-data/standard-novel/program.json','utf8'))),shore=standard.assets.find(a=>a.id==='shore');if(!shore)throw new Error('shore');const b=new ProgramBuilder({gameId:'lighthouse-interactive',title:'燈塔來信 · 光中的選擇',release:'interactive-1',entry:'main'}),background=b.asset('image',{...shore,path:'../'+shore.path}),route=variable('route','string');b.global({...route,initial:string('')});
const clips=[];for(const [id,file]of [['beacon','beacon-opus.webm'],['vorbis','beacon-vorbis.webm'],['silent','beacon-silent.webm']] as const){const bytes=await readFile('tests/fixtures/game-data/interactive-novel/assets/'+file);await writeFile(root+'/assets/'+file,bytes);clips.push(b.asset('video',{id,path:'assets/'+file,mime:'video/webm',sha256:createHash('sha256').update(bytes).digest('hex')}));}const movie=clips[0],silent=clips[2];if(!movie||!silent)throw new Error('clips');const page=(at:string,content:string)=>instruction('text.page',{at,textId:at.replace(':','.'),revision:'zh-1',speaker:'澪',content});
b.function({id:'main',entry:'signal:stage',layout:1,params:[],locals:[],returns:'void',code:[imagePut('signal:stage','background',background,{x:0,y:0,alpha:1}),page('signal:welcome','燈光會替我們回答嗎？先看看遠方傳來的影像吧。'),videoPlay('signal:movie','opening',movie,{gain:.35,skippable:true,restore:'replay'}),page('signal:after','光影停下後，兩個回信的位置出現在海面上。你可以點選，也可以用鍵盤選擇。'),interactionPrompt('signal:hotspot',route,'選擇回信的方向',[{id:'shore',label:'點亮海岸',target:'signal:shore',rect:{x:180,y:280,width:300,height:140}},{id:'tower',label:'點亮燈塔',target:'signal:tower',rect:{x:800,y:280,width:300,height:140}},{id:'sealed',label:'尚未開啟',target:'signal:tower',enabled:E.flag(false),rect:{x:520,y:280,width:240,height:140}}]),page('signal:shore','我們把海岸的燈點亮，讓遠方的人看見歸路。'),instruction('control.jump',{at:'signal:shore-join',target:'signal:timed'}),page('signal:tower','我們守住燈塔的光，等待下一次回聲。'),instruction('control.jump',{at:'signal:tower-join',target:'signal:timed'}),interactionPrompt('signal:timed',route,'潮聲到來以前，要把信寄出去嗎？',[{id:'send',label:'現在寄出',target:'signal:send'},{id:'keep',label:'再等一會',target:'signal:wait'}],{deadlineMs:6000,timeout:{id:'tide',target:'signal:timeout'}}),page('signal:send','你趕在潮聲之前寄出了信。這一次，回聲會知道我們的名字。'),instruction('control.jump',{at:'signal:send-join',target:'signal:final-movie'}),page('signal:wait','你把信留在燈下，讓每一句話再多停留片刻。'),instruction('control.jump',{at:'signal:wait-join',target:'signal:final-movie'}),page('signal:timeout','潮聲先一步來了。澪輕輕收好信紙，約定明天再來。'),videoPlay('signal:final-movie','final',silent,{skippable:false,restore:'forbid'}),page('signal:ending','不論回信何時出發，燈始終亮著。'),instruction('profile.set',{at:'signal:unlock',key:'interactiveComplete',value:bool(true)}),instruction('control.end',{at:'signal:end'})]});const program=b.build(),resources=await Promise.all(program.assets.map(async a=>inspectResource(a,new Uint8Array(await readFile(path.resolve(root,a.path))),bytes=>new TextDecoder('utf8',{fatal:true}).decode(bytes))));const release=await createReleaseManifest({program,series:'1',resources},{async sha256(text){return createHash('sha256').update(text).digest('hex');}});for(const target of [root,'tests/fixtures/game-data/interactive-novel']){await mkdir(target,{recursive:true});await writeFile(target+'/program.json',JSON.stringify(program,null,2)+'\n');await writeFile(target+'/program.json.release.json',JSON.stringify(release,null,2)+'\n');}console.log('Built original interactive chapter using production video/hotspot/timed factories');
